/**
 * Get message info (size and magic numbers) for a given message ID.
 * @param msg_id The message ID
 * @param info Pointer to message_info_t struct to fill
 * @return true if message ID is known, false otherwise
 */
static inline bool sf_system_get_message_info(uint16_t msg_id, message_info_t* info) {
    switch (msg_id) {
        case SF_SYSTEM_HEARTBEAT_MSG_ID:
            info->size = SF_SYSTEM_HEARTBEAT_MAX_SIZE;
            info->base_size = SF_SYSTEM_HEARTBEAT_BASE_SIZE;
            info->min_size = SF_SYSTEM_HEARTBEAT_BASE_SIZE;
            info->magic1 = SF_SYSTEM_HEARTBEAT_MAGIC1;
            info->magic2 = SF_SYSTEM_HEARTBEAT_MAGIC2;
            return true;
        case SF_SYSTEM_LINK_STATS_MSG_ID:
            info->size = SF_SYSTEM_LINK_STATS_MAX_SIZE;
            info->base_size = SF_SYSTEM_LINK_STATS_BASE_SIZE;
            info->min_size = SF_SYSTEM_LINK_STATS_BASE_SIZE;
            info->magic1 = SF_SYSTEM_LINK_STATS_MAGIC1;
            info->magic2 = SF_SYSTEM_LINK_STATS_MAGIC2;
            return true;
        case SF_SYSTEM_LINK_TEST_ACK_MSG_ID:
            info->size = SF_SYSTEM_LINK_TEST_ACK_MAX_SIZE;
            info->base_size = SF_SYSTEM_LINK_TEST_ACK_BASE_SIZE;
            info->min_size = SF_SYSTEM_LINK_TEST_ACK_BASE_SIZE;
            info->magic1 = SF_SYSTEM_LINK_TEST_ACK_MAGIC1;
            info->magic2 = SF_SYSTEM_LINK_TEST_ACK_MAGIC2;
            return true;
        case SF_SYSTEM_LINK_TEST_DATA_MSG_ID:
            info->size = SF_SYSTEM_LINK_TEST_DATA_MAX_SIZE;
            info->base_size = SF_SYSTEM_LINK_TEST_DATA_BASE_SIZE;
            info->min_size = SF_SYSTEM_LINK_TEST_DATA_BASE_SIZE;
            info->magic1 = SF_SYSTEM_LINK_TEST_DATA_MAGIC1;
            info->magic2 = SF_SYSTEM_LINK_TEST_DATA_MAGIC2;
            return true;
        case SF_SYSTEM_LINK_TEST_REPORT_MSG_ID:
            info->size = SF_SYSTEM_LINK_TEST_REPORT_MAX_SIZE;
            info->base_size = SF_SYSTEM_LINK_TEST_REPORT_BASE_SIZE;
            info->min_size = SF_SYSTEM_LINK_TEST_REPORT_BASE_SIZE;
            info->magic1 = SF_SYSTEM_LINK_TEST_REPORT_MAGIC1;
            info->magic2 = SF_SYSTEM_LINK_TEST_REPORT_MAGIC2;
            return true;
        case SF_SYSTEM_LINK_TEST_START_MSG_ID:
            info->size = SF_SYSTEM_LINK_TEST_START_MAX_SIZE;
            info->base_size = SF_SYSTEM_LINK_TEST_START_BASE_SIZE;
            info->min_size = SF_SYSTEM_LINK_TEST_START_BASE_SIZE;
            info->magic1 = SF_SYSTEM_LINK_TEST_START_MAGIC1;
            info->magic2 = SF_SYSTEM_LINK_TEST_START_MAGIC2;
            return true;
        case SF_SYSTEM_LINK_TEST_STOP_MSG_ID:
            info->size = SF_SYSTEM_LINK_TEST_STOP_MAX_SIZE;
            info->base_size = SF_SYSTEM_LINK_TEST_STOP_BASE_SIZE;
            info->min_size = SF_SYSTEM_LINK_TEST_STOP_BASE_SIZE;
            info->magic1 = SF_SYSTEM_LINK_TEST_STOP_MAGIC1;
            info->magic2 = SF_SYSTEM_LINK_TEST_STOP_MAGIC2;
            return true;
        case SF_SYSTEM_PING_MSG_ID:
            info->size = SF_SYSTEM_PING_MAX_SIZE;
            info->base_size = SF_SYSTEM_PING_BASE_SIZE;
            info->min_size = SF_SYSTEM_PING_BASE_SIZE;
            info->magic1 = SF_SYSTEM_PING_MAGIC1;
            info->magic2 = SF_SYSTEM_PING_MAGIC2;
            return true;
        case SF_SYSTEM_PONG_MSG_ID:
            info->size = SF_SYSTEM_PONG_MAX_SIZE;
            info->base_size = SF_SYSTEM_PONG_BASE_SIZE;
            info->min_size = SF_SYSTEM_PONG_BASE_SIZE;
            info->magic1 = SF_SYSTEM_PONG_MAGIC1;
            info->magic2 = SF_SYSTEM_PONG_MAGIC2;
            return true;
        case SF_SYSTEM_RPC_REQUEST_MSG_ID:
            info->size = SF_SYSTEM_RPC_REQUEST_MAX_SIZE;
            info->base_size = SF_SYSTEM_RPC_REQUEST_BASE_SIZE;
            info->min_size = SF_SYSTEM_RPC_REQUEST_BASE_SIZE;
            info->magic1 = SF_SYSTEM_RPC_REQUEST_MAGIC1;
            info->magic2 = SF_SYSTEM_RPC_REQUEST_MAGIC2;
            return true;
        case SF_SYSTEM_RPC_RESPONSE_MSG_ID:
            info->size = SF_SYSTEM_RPC_RESPONSE_MAX_SIZE;
            info->base_size = SF_SYSTEM_RPC_RESPONSE_BASE_SIZE;
            info->min_size = SF_SYSTEM_RPC_RESPONSE_BASE_SIZE;
            info->magic1 = SF_SYSTEM_RPC_RESPONSE_MAGIC1;
            info->magic2 = SF_SYSTEM_RPC_RESPONSE_MAGIC2;
            return true;
        default: break;
    }
    return false;
}

